def integer_cube_root(n):
    k = int(round(n ** (1 / 3)))
    while k ** 3 > n:
        k -= 1
    while (k + 1) ** 3 <= n:
        k += 1
    return k

def intersperse(lst, sep):
    def helper(rest):
        if len(rest) <= 1:
            return list(rest)
        return [rest[0], sep] + helper(rest[1:])
    return helper(lst)

def merge_keys_case_insensitive(d):
    import functools
    def combine(acc, item):
        key, value = item
        lk = key.lower()
        acc[lk] = acc.get(lk, 0) + value
        return acc
    return functools.reduce(combine, d.items(), {})

