def partition_odd_even(lst):
    from itertools import filterfalse
    is_even = lambda x: x % 2 == 0
    evens = list(filter(is_even, lst))
    odds = list(filterfalse(is_even, lst))
    return (evens, odds)

def is_self_number(n):
    def digit_sum(x):
        total = 0
        while x > 0:
            total += x % 10
            x //= 10
        return total
    lo = max(0, n - 100)
    return not any(m + digit_sum(m) == n for m in range(lo, n))

