        return []
    window = len(sub)
    positions = range(len(s) - window + 1)
    return [i for i in positions if s.startswith(sub, i)]

def sum_of_prime_factors(n):
    factors = set()
    remaining = n
    divisor = 2
    while divisor * divisor <= remaining:
        while remaining % divisor == 0:
            factors.add(divisor)
            remaining //= divisor
        divisor += 1
    if remaining > 1:
        factors.add(remaining)
    return sum(factors)

def mod_pow(base, exp, mod):
    if exp == 0:
        return 1 % mod
    half = mod_pow(base, exp // 2, mod)
    result = (half * half) % mod
    if exp % 2 == 1:
        result = (result * base) % mod
    return result

