def max_sum_subarray_of_size_k(lst, k):
    prefix = [0]
    for x in lst:
        prefix.append(prefix[-1] + x)
    best = prefix[k] - prefix[0]
    for i in range(1, len(lst) - k + 1):
        window_sum = prefix[i + k] - prefix[i]
        if window_sum > best:
            best = window_sum
    return best

