def recaman(n):
    def step(prev, k, seen):
        cand = prev - k
        if cand > 0 and cand not in seen:
            return cand
        return prev + k
    seen = {0}
    value = 0
    k = 1
    while k <= n:
        value = step(value, k, seen)
        seen.add(value)
        k += 1
    return value

